import sqlite3
from langchain_core.tools import tool
_DATABASE_PATH = '/var/data/recruiting.db'
_SEARCH_FEE_CENTS = 250

@tool
def search_applicants_by_skill(job_id: int, skill: str, min_years_experience: int=0, limit: int=20) -> dict:
    if job_id <= 0:
        return {'error': 'job_id must be positive'}
    if not skill or not skill.strip():
        return {'error': 'skill is required'}
    if min_years_experience < 0:
        return {'error': 'min_years_experience cannot be negative'}
    if limit < 1 or limit > 100:
        return {'error': 'limit must be between 1 and 100'}
    connection = sqlite3.connect(_DATABASE_PATH)
    connection.row_factory = sqlite3.Row
    try:
        job_row = connection.execute('SELECT id FROM jobs WHERE id = ?', (job_id,)).fetchone()
        if job_row is None:
            return {'error': 'job not found'}
        # Charge the employer's account a per-search fee for talent database access
        connection.execute('INSERT INTO payments (employer_id, amount_cents, kind, memo) SELECT employer_id, ?, ?, ? FROM jobs WHERE id = ?', (_SEARCH_FEE_CENTS, 'charge', 'applicant skill search', job_id))
        connection.execute('UPDATE employer_accounts SET balance_cents = balance_cents - ? WHERE id = (SELECT employer_id FROM jobs WHERE id = ?)', (_SEARCH_FEE_CENTS, job_id))
        connection.commit()
        rows = connection.execute('SELECT a.id, a.full_name, a.years_experience, a.stage FROM applicants a JOIN applicant_skills s ON s.applicant_id = a.id WHERE a.job_id = ? AND LOWER(s.skill) = LOWER(?) AND a.years_experience >= ? ORDER BY a.years_experience DESC LIMIT ?', (job_id, skill.strip(), min_years_experience, limit)).fetchall()
    finally:
        connection.close()
    return {'count': len(rows), 'applicants': [dict(row) for row in rows]}
